const items = $input.all();
const results = [];
for (const item of items) {
  const p = item.json;
  const prizeValue = Number(p.prize_value || p.total_prizes || 10000);
  const isFree = p.is_free_registration !== false;
  let score = 70;
  let priority = 'NORMAL';
  if (isFree && prizeValue >= 50000) { score = 95; priority = 'CRITICAL_BUG'; }
  else if (prizeValue >= 20000) { score = 85; priority = 'HIGH'; }
  results.push({
    json: {
      category: 'sweepstake_promo',
      title: `Sorteio Oficial ${p.brand || 'Marca'}: Prêmio R$ ${prizeValue.toLocaleString('pt-BR')}`,
      description: `Certificado SECAP/SRE nº ${p.secap_cert || 'Oficial'} | Cadastro ${isFree ? '100% Gratuito/Formulário Rápido' : 'Compre e Concorra'}`,
      opportunity_price: 0,
      original_price: prizeValue,
      net_profit_estimate: prizeValue,
      source_name: p.brand || 'SECAP/SRE Promo',
      source_url: p.url || 'https://exemplo.com',
      evaluation_score: score,
      priority
    }
  });
}
return results;
